                <div class="facet-check"></div>
                <span class="facet-label">${v.label}</span>
                <span class="facet-count ${count === 0 ? 'zero' : ''}">${count}</span>
              </div>`;
          }).join('')}
        </div>
      </div>`;
  }).join

